CREATE TABLE categories(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,code varchar(64) NOT NULL,name varchar(120) NOT NULL,status text NOT NULL DEFAULT 'ACTIVE' CHECK(status IN ('ACTIVE','INACTIVE')),version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),UNIQUE(tenant_id,code));
CREATE TABLE products(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,name varchar(120) NOT NULL,category_id uuid,status text NOT NULL DEFAULT 'ACTIVE' CHECK(status IN ('ACTIVE','INACTIVE')),version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,category_id) REFERENCES categories(tenant_id,id));
CREATE TABLE skus(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,product_id uuid NOT NULL,code varchar(64) NOT NULL,name varchar(120) NOT NULL,barcode varchar(64),base_unit varchar(30) NOT NULL,attributes jsonb NOT NULL DEFAULT '{}',status text NOT NULL DEFAULT 'ACTIVE' CHECK(status IN ('ACTIVE','INACTIVE')),version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),UNIQUE(tenant_id,code),UNIQUE(tenant_id,barcode),FOREIGN KEY(tenant_id,product_id) REFERENCES products(tenant_id,id));
CREATE TABLE units(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,sku_id uuid NOT NULL,name varchar(30) NOT NULL,factor numeric(18,3) NOT NULL CHECK(factor>0),price_vnd numeric(20,0) NOT NULL CHECK(price_vnd>=0),is_base boolean NOT NULL DEFAULT false,status text NOT NULL DEFAULT 'ACTIVE' CHECK(status IN ('ACTIVE','INACTIVE')),version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),UNIQUE(tenant_id,sku_id,name),FOREIGN KEY(tenant_id,sku_id) REFERENCES skus(tenant_id,id),CHECK(NOT is_base OR factor=1));
CREATE UNIQUE INDEX one_base_unit ON units(tenant_id,sku_id) WHERE is_base;
CREATE TABLE price_history(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,unit_id uuid NOT NULL,price_vnd numeric(20,0) NOT NULL,version integer NOT NULL,actor text NOT NULL,effective_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(tenant_id,unit_id) REFERENCES units(tenant_id,id));
CREATE TABLE idempotency(scope text NOT NULL,key text NOT NULL,body_hash text NOT NULL,response jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(scope,key));
CREATE TABLE audit(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,actor text NOT NULL,action text NOT NULL,entity_id uuid NOT NULL,before_data jsonb,after_data jsonb,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE inbox(id uuid PRIMARY KEY,processed_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE outbox(id uuid PRIMARY KEY,type text NOT NULL,payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),lease_until timestamptz,delivered_at timestamptz);
CREATE INDEX products_tenant ON products(tenant_id,id);
CREATE INDEX skus_product ON skus(tenant_id,product_id);
CREATE INDEX outbox_pending ON outbox(created_at) WHERE delivered_at IS NULL;
